#pragma once

#include <array>
#include <functional>
#include <span>
#include <tuple>
#include <vector>

#include <ruckig/error.hpp>
#include <ruckig/profile.hpp>


namespace ruckig {

template<size_t, template<class, size_t> class> class TargetCalculator;
template<size_t, template<class, size_t> class> class WaypointsCalculator;


//! The trajectory generated by the Ruckig algorithm.
template<size_t DOFs = 0, template<class, size_t> class CustomVector = StandardVector>
class Trajectory {
#if defined WITH_CLOUD_CLIENT
    template<class T> using Container = std::vector<T>;
#else
    template<class T> using Container = std::array<T, 1>;
#endif

    template<class T> using Vector = CustomVector<T, DOFs>;

    friend class TargetCalculator<DOFs, CustomVector>;
    friend class WaypointsCalculator<DOFs, CustomVector>;
    template<size_t, template<class, size_t> class, bool> friend class Ruckig;
    template<size_t, template<class, size_t> class> friend class OutputParameter;

    Container<Vector<Profile>> profiles;
    // Allocated only for explicit local multi-waypoint calculations.
    std::vector<Vector<Profile>> local_profiles;
    std::vector<double> local_cumulative_times;

    double duration {0.0};
    bool calculated {false};
    bool profiles_calculated {false};
#if defined WITH_CLOUD_CLIENT
    // The cloud path does not populate independent minimum durations.
    bool independent_min_durations_available {true};
#endif
    Container<double> cumulative_times;

    Vector<double> independent_min_durations;

    size_t continue_calculation_counter {0};

    std::span<const Vector<Profile>> profiles_view() const {
        return local_profiles.empty() ? std::span<const Vector<Profile>>(profiles) : std::span<const Vector<Profile>>(local_profiles);
    }

    std::span<const double> times_view() const {
        return local_profiles.empty() ? std::span<const double>(cumulative_times) : std::span<const double>(local_cumulative_times);
    }

    bool has_valid_profile_structure() const {
        const auto active_profiles = profiles_view();
        return degrees_of_freedom > 0 && (DOFs == 0 || degrees_of_freedom == DOFs)
            && !active_profiles.empty() && active_profiles.front().size() == degrees_of_freedom
            && times_view().size() == active_profiles.size();
    }

#if defined WITH_CLOUD_CLIENT
    template<size_t D = DOFs, typename std::enable_if<(D >= 1), int>::type = 0>
    void resize(size_t max_number_of_waypoints) {
        profiles.resize(max_number_of_waypoints + 1);
        cumulative_times.resize(max_number_of_waypoints + 1);
    }

    template<size_t D = DOFs, typename std::enable_if<(D == 0), int>::type = 0>
    void resize(size_t max_number_of_waypoints) {
        resize<1>(max_number_of_waypoints); // Also call resize method above

        for (auto& p: profiles) {
            p.resize(degrees_of_freedom);
        }
    }
#endif

    //! Calculates the base values to then integrate from
    template<typename Func>
    void state_to_integrate_from(double time, size_t& new_section, Func&& set_integrate) const {
        if (!calculated || !has_valid_profile_structure() || !std::isfinite(time)) {
            throw RuckigError("trajectory sampling requires a calculated trajectory, matching dimensions, and a finite time.");
        }
        const auto profiles = profiles_view();
        const auto cumulative_times = times_view();
        if (time >= duration) {
            // Keep constant acceleration
            new_section = profiles.size();
            const auto& profiles_dof = profiles.back();
            for (size_t dof = 0; dof < degrees_of_freedom; ++dof) {
                const double t_pre = ((profiles.size() > 1) ? cumulative_times[cumulative_times.size() - 2] : 0.0) + profiles_dof[dof].brake.duration;
                const double t_diff = time - (t_pre + profiles_dof[dof].t_sum.back());
                set_integrate(dof, t_diff, profiles_dof[dof].p.back(), profiles_dof[dof].v.back(), profiles_dof[dof].a.back(), 0.0);
            }
            return;
        }

        const auto new_section_ptr = std::upper_bound(cumulative_times.begin(), cumulative_times.end(), time);
        new_section = std::distance(cumulative_times.begin(), new_section_ptr);
        double t_diff = time;
        if (new_section > 0) {
            t_diff -= cumulative_times[new_section - 1];
        }

        for (size_t dof = 0; dof < degrees_of_freedom; ++dof) {
            const Profile& p = profiles[new_section][dof];
            double t_diff_dof = t_diff;

            // Brake pre-trajectory
            if (p.brake.duration > 0) {
                if (t_diff_dof < p.brake.duration) {
                    const size_t index = (t_diff_dof < p.brake.t[0]) ? 0 : 1;
                    if (index > 0) {
                        t_diff_dof -= p.brake.t[index - 1];
                    }

                    set_integrate(dof, t_diff_dof, p.brake.p[index], p.brake.v[index], p.brake.a[index], p.brake.j[index]);
                    continue;
                } else {
                    t_diff_dof -= p.brake.duration;
                }
            }

            // Accel post-trajectory
            // if (new_section == profiles.size() - 1 && p.accel.duration > 0) {
            //     if (t_diff_dof > p.t_sum.back()) {
            //         const size_t index = (t_diff_dof < p.accel.t[1]) ? 1 : 0;
            //         if (index > 0) {
            //             t_diff_dof -= p.accel.t[index - 1];
            //         }

            //         t_diff_dof -= p.t_sum.back();

            //         if (t_diff_dof < p.accel.t[1]) {
            //             set_integrate(dof, t_diff_dof, p.p.back(), p.v.back(), p.a.back(), p.accel.j[1]);
            //             continue;
            //         }

            //         t_diff_dof -= p.accel.t[1];

            //         const size_t index = 1;
            //         set_integrate(dof, t_diff_dof, p.accel.p[index], p.accel.v[index], p.accel.a[index], p.accel.j[index]);
            //         continue;
            //     }
            // }

            // Non-time synchronization
            if (t_diff_dof >= p.t_sum.back()) {
                // Keep constant acceleration
                set_integrate(dof, t_diff_dof - p.t_sum.back(), p.p.back(), p.v.back(), p.a.back(), 0.0);
                continue;
            }

            const auto index_dof_ptr = std::upper_bound(p.t_sum.begin(), p.t_sum.end(), t_diff_dof);
            const size_t index_dof = std::distance(p.t_sum.begin(), index_dof_ptr);

            if (index_dof > 0) {
                t_diff_dof -= p.t_sum[index_dof - 1];
            }

            set_integrate(dof, t_diff_dof, p.p[index_dof], p.v[index_dof], p.a[index_dof], p.j[index_dof]);
        }
    }

    Bound get_position_extrema_for_dof(size_t dof) const {
        const auto profiles = profiles_view();
        const auto cumulative_times = times_view();
        Bound extrema {std::numeric_limits<double>::infinity(), -std::numeric_limits<double>::infinity(), 0.0, 0.0};
        double section_start = 0.0;
        for (size_t section = 0; section < profiles.size(); ++section) {
            const auto& profile = profiles[section][dof];
            auto bound = profile.get_position_extrema();
            const double profile_end = profile.brake.duration + profile.t_sum.back();
            const double tail_duration = cumulative_times[section] - section_start - profile_end;
            if (tail_duration > 0.0) {
                // Unsynchronized and disabled axes continue at constant acceleration.
                Profile::check_step_for_position_extremum(profile_end, tail_duration,
                    profile.p.back(), profile.v.back(), profile.a.back(), 0.0, bound);
            }
            if (bound.min < extrema.min) {
                extrema.min = bound.min;
                extrema.t_min = section_start + bound.t_min;
            }
            if (bound.max > extrema.max) {
                extrema.max = bound.max;
                extrema.t_max = section_start + bound.t_max;
            }
            section_start = cumulative_times[section];
        }
        return extrema;
    }

    bool check_position_limits(const Vector<double>& min_position, const Vector<double>& max_position) const {
        constexpr double position_tolerance = 1e-8;
        for (size_t dof = 0; dof < degrees_of_freedom; ++dof) {
            if (std::isinf(min_position[dof]) && std::isinf(max_position[dof])) {
                continue;
            }
            const auto bound = get_position_extrema_for_dof(dof);
            if (!std::isfinite(bound.min) || !std::isfinite(bound.max)
                || bound.min < min_position[dof] - position_tolerance || bound.max > max_position[dof] + position_tolerance) {
                return false;
            }
        }
        return true;
    }

public:
    size_t degrees_of_freedom;

    template<size_t D = DOFs, typename std::enable_if<(D >= 1), int>::type = 0>
    Trajectory(): degrees_of_freedom(DOFs) {
#if defined WITH_CLOUD_CLIENT
        resize(0);
#endif
    }

    template<size_t D = DOFs, typename std::enable_if<(D == 0), int>::type = 0>
    Trajectory(size_t dofs): degrees_of_freedom(dofs) {
#if defined WITH_CLOUD_CLIENT
        resize(0);
#endif

        profiles[0].resize(dofs);
        independent_min_durations.resize(dofs);
    }

#if defined WITH_CLOUD_CLIENT
    template<size_t D = DOFs, typename std::enable_if<(D >= 1), int>::type = 0>
    Trajectory(size_t max_number_of_waypoints): degrees_of_freedom(DOFs) {
        resize(max_number_of_waypoints);
    }

    template<size_t D = DOFs, typename std::enable_if<(D == 0), int>::type = 0>
    Trajectory(size_t dofs, size_t max_number_of_waypoints): degrees_of_freedom(dofs) {
        resize(max_number_of_waypoints);

        independent_min_durations.resize(dofs);
    }
#endif

    //! Get the kinematic state, the jerk, and the section at a given time
    void at_time(double time, Vector<double>& new_position, Vector<double>& new_velocity, Vector<double>& new_acceleration, Vector<double>& new_jerk, size_t& new_section) const {
        if constexpr (DOFs == 0) {
            if (degrees_of_freedom != new_position.size() || degrees_of_freedom != new_velocity.size() || degrees_of_freedom != new_acceleration.size() || degrees_of_freedom != new_jerk.size()) {
                throw RuckigError("mismatch in degrees of freedom (vector size).");
            }
        }

        state_to_integrate_from(time, new_section, [&](size_t dof, double t, double p, double v, double a, double j) {
            std::tie(new_position[dof], new_velocity[dof], new_acceleration[dof]) = integrate(t, p, v, a, j);
            new_jerk[dof] = j;
        });
    }

    //! Get the kinematic state at a given time
    //! The Python wrapper takes `time` as an argument, and returns `new_position`, `new_velocity`, and `new_acceleration` instead.
    void at_time(double time, Vector<double>& new_position, Vector<double>& new_velocity, Vector<double>& new_acceleration) const {
        if constexpr (DOFs == 0) {
            if (degrees_of_freedom != new_position.size() || degrees_of_freedom != new_velocity.size() || degrees_of_freedom != new_acceleration.size()) {
                throw RuckigError("mismatch in degrees of freedom (vector size).");
            }
        }

        size_t new_section;
        state_to_integrate_from(time, new_section, [&](size_t dof, double t, double p, double v, double a, double j) {
            std::tie(new_position[dof], new_velocity[dof], new_acceleration[dof]) = integrate(t, p, v, a, j);
        });
    }

    //! Get the kinematic state directly into caller-owned contiguous buffers.
    void at_time(double time, std::span<double> new_position, std::span<double> new_velocity, std::span<double> new_acceleration) const {
        if (degrees_of_freedom != new_position.size() || degrees_of_freedom != new_velocity.size() || degrees_of_freedom != new_acceleration.size()) {
            throw RuckigError("mismatch in degrees of freedom (vector size).");
        }
        size_t new_section;
        state_to_integrate_from(time, new_section, [&](size_t dof, double t, double p, double v, double a, double j) {
            std::tie(new_position[dof], new_velocity[dof], new_acceleration[dof]) = integrate(t, p, v, a, j);
        });
    }

    //! Get the position at a given time
    void at_time(double time, Vector<double>& new_position) const {
        if constexpr (DOFs == 0) {
            if (degrees_of_freedom != new_position.size()) {
                throw RuckigError("mismatch in degrees of freedom (vector size).");
            }
        }

        size_t new_section;
        state_to_integrate_from(time, new_section, [&](size_t dof, double t, double p, double v, double a, double j) {
            std::tie(new_position[dof], std::ignore, std::ignore) = integrate(t, p, v, a, j);
        });
    }

    //! Get the kinematic state, the jerk, and the section at a given time without vectors for a single DoF
    template<size_t D = DOFs, typename std::enable_if<(D == 1), int>::type = 0>
    void at_time(double time, double& new_position, double& new_velocity, double& new_acceleration, double& new_jerk, size_t& new_section) const {
        state_to_integrate_from(time, new_section, [&](size_t, double t, double p, double v, double a, double j) {
            std::tie(new_position, new_velocity, new_acceleration) = integrate(t, p, v, a, j);
            new_jerk = j;
        });
    }

    //! Get the kinematic state at a given time without vectors for a single DoF
    template<size_t D = DOFs, typename std::enable_if<(D == 1), int>::type = 0>
    void at_time(double time, double& new_position, double& new_velocity, double& new_acceleration) const {
        size_t new_section;
        state_to_integrate_from(time, new_section, [&](size_t, double t, double p, double v, double a, double j) {
            std::tie(new_position, new_velocity, new_acceleration) = integrate(t, p, v, a, j);
        });
    }

    //! Get the position at a given time without vectors for a single DoF
    template<size_t D = DOFs, typename std::enable_if<(D == 1), int>::type = 0>
    void at_time(double time, double& new_position) const {
        size_t new_section;
        state_to_integrate_from(time, new_section, [&](size_t, double t, double p, double v, double a, double j) {
            std::tie(new_position, std::ignore, std::ignore) = integrate(t, p, v, a, j);
        });
    }

    //! Get the kinematic state at multiple times
    //! The Python wrapper takes `times` as an argument, and returns `positions`, `velocities`, and `accelerations` instead.
    template<class Times, class States>
    void at_times(const Times& times, States& positions, States& velocities, States& accelerations) const {
        if (positions.size() != times.size() || velocities.size() != times.size() || accelerations.size() != times.size()) {
            throw RuckigError("mismatch in number of samples (vector size).");
        }
        for (size_t i = 0; i < times.size(); ++i) {
            at_time(times[i], positions[i], velocities[i], accelerations[i]);
        }
    }

    //! Get the underlying profiles of the trajectory (only in the Ruckig Community Version)
    std::vector<Vector<Profile>> get_profiles() const {
        if ((!calculated && !profiles_calculated) || !has_valid_profile_structure()) {
            throw RuckigError("trajectory profiles require a calculated trajectory.");
        }
        const auto view = profiles_view();
        return {view.begin(), view.end()};
    }

    //! Get the duration of the (synchronized) trajectory
    double get_duration() const {
        return duration;
    }

    //! Get the durations when the intermediate waypoints are reached
    std::vector<double> get_intermediate_durations() const {
        if ((!calculated && !profiles_calculated) || !has_valid_profile_structure()) {
            throw RuckigError("intermediate durations require a calculated trajectory.");
        }
        const auto view = times_view();
        return {view.begin(), view.end()};
    }

    //! Get the minimum duration of each independent DoF
    //! Cloud trajectories do not provide this diagnostic and raise RuckigError.
    Vector<double> get_independent_min_durations() const {
        if ((!calculated && !profiles_calculated) || !has_valid_profile_structure()) {
            throw RuckigError("independent durations require a calculated trajectory.");
        }
#if defined WITH_CLOUD_CLIENT
        if (!independent_min_durations_available) {
            throw RuckigError("independent durations are unavailable for cloud trajectories.");
        }
#endif
        return independent_min_durations;
    }

    //! Get the min/max values of the position for each DoF
    void get_position_extrema(CustomVector<Bound, DOFs>& position_extrema) const {
        if ((!calculated && !profiles_calculated) || !has_valid_profile_structure()) {
            throw RuckigError("position extrema require a calculated trajectory.");
        }
        if (position_extrema.size() != degrees_of_freedom) {
            throw RuckigError("mismatch in degrees of freedom (vector size).");
        }
        for (size_t dof = 0; dof < degrees_of_freedom; ++dof) {
            position_extrema[dof] = get_position_extrema_for_dof(dof);
        }
    }

    //! Get the time that this trajectory passes a specific position of a given DoF the first time
    std::optional<double> get_first_time_at_position(size_t dof, double position, double time_after=0.0) const {
        if (!calculated || !has_valid_profile_structure() || dof >= degrees_of_freedom || !std::isfinite(position) || !std::isfinite(time_after)) {
            return std::nullopt;
        }
        const auto profiles = profiles_view();
        const auto cumulative_times = times_view();

        const auto find_in_step = [&](double start, double duration, double p, double v, double a, double j) -> std::optional<double> {
            const double earliest = std::max(0.0, time_after - start);
            if (earliest > duration) {
                return std::nullopt;
            }
            if (std::abs(std::get<0>(integrate(earliest, p, v, a, j)) - position) < 1e-9) {
                return start + earliest;
            }
            std::optional<double> first;
            for (double t: roots::solve_cubic(j / 6, a / 2, v, p - position)) {
                if (earliest <= t && t <= duration && (!first || t < *first)) {
                    first = t;
                }
            }
            if (!first && std::abs(std::get<0>(integrate(duration, p, v, a, j)) - position) < 1e-9) {
                first = duration;
            }
            return first ? std::optional<double>(start + *first) : std::nullopt;
        };
        for (size_t i = 0; i < profiles.size(); ++i) {
            const double section_time = (i > 0) ? cumulative_times[i-1] : 0.0;
            const auto& profile = profiles[i][dof];
            double start = section_time;
            if (profile.brake.duration > 0.0) {
                for (size_t step = 0; step < 2; ++step) {
                    if (profile.brake.t[step] > 0.0) {
                        if (auto time = find_in_step(start, profile.brake.t[step], profile.brake.p[step], profile.brake.v[step], profile.brake.a[step], profile.brake.j[step])) {
                            return time;
                        }
                        start += profile.brake.t[step];
                    }
                }
            }
            if (profile.t_sum.back() > 0.0) {
                for (size_t step = 0; step < 7; ++step) {
                    if (profile.t[step] > 0.0) {
                        if (auto time = find_in_step(start, profile.t[step], profile.p[step], profile.v[step], profile.a[step], profile.j[step])) {
                            return time;
                        }
                        start += profile.t[step];
                    }
                }
            }
            if (auto time = find_in_step(start, std::max(0.0, cumulative_times[i] - start), profile.p.back(), profile.v.back(), profile.a.back(), 0.0)) {
                return time;
            }
        }
        return std::nullopt;
    }
};

} // namespace ruckig
